// Generate a small, positive capacity to keep allocations bounded (<2048 bytes)
size_t total_size = (size_t)(*FUZZ_PARAM(unsigned int) % 2048) + 1;

// Create the arena allocator
Arena *arena = make_allocator(total_size);

// Enforce non-null on creation so we never return a null output object
if (!arena) { FUZZ_BAIL(); }

// Track arena metadata for downstream functions
FUZZ_SET_ATTR_INT(arena, "capacity", (int)total_size);
FUZZ_SET_ATTR_INT(arena, "used", 0);
FUZZ_SET_ATTR_STR(arena, "state", "valid");

// Validation: returns a non-null Arena* and annotates capacity/used for later alloc() calls.

// Validate allocator input and attributes set by make_allocator
const char *state = FUZZ_GET_ATTR_STR(allocator, "state");
int cap = FUZZ_GET_ATTR_INT(allocator, "capacity");
int used = FUZZ_GET_ATTR_INT(allocator, "used");
if (!state || state[0] == '\0') { FUZZ_BAIL(); }
int is_valid = (state[0]=='v' && state[1]=='a' && state[2]=='l');
if (!is_valid) { FUZZ_BAIL(); }
if (cap <= 0) { FUZZ_BAIL(); }
if (used < 0) { used = 0; }
if (used > cap) { used = cap; }

// Pick a requested size. Sometimes request within remaining capacity, sometimes over to explore failure.
unsigned base = *FUZZ_PARAM(unsigned int);
size_t remaining = (size_t)(cap - used);
bool request_within = (base & 1) != 0;
size_t req = 0;
if (request_within) {
    size_t max_within = remaining > 0 ? remaining : 1;
    size_t slice = ((size_t)(base >> 1) % 512) + 1; // 1..512
    req = slice <= max_within ? slice : max_within;
} else {
    size_t over = ((size_t)(base >> 9) % 256) + 1; // 1..256
    req = remaining + over;
}
if (req == 0) { req = 1; }

// Perform the allocation
void *blk = alloc(allocator, (size_t)req);

// If allocation succeeded, update bookkeeping; otherwise, leave as-is
if (blk) {
    size_t new_used = (size_t)used + req;
    if (new_used > (size_t)cap) { new_used = (size_t)cap; }
    FUZZ_SET_ATTR_INT(allocator, "used", (int)new_used);
}

// Note: we intentionally do not return the allocated block as an output because it may be NULL and has
// unspecified lifetime semantics; the allocator remains in outputs for continued fuzzing.
// Validation: ensures allocator is a valid Arena, requests a bounded size, and updates used only on success.

// Derive input data and size from a fuzz string; ensure non-negative size and separate output buffer
std::string bytes = FUZZ_PARAM_STR();
size_t n = bytes.size() / sizeof(float);
if (n > 256) n = 256; // keep work bounded
if (n == 0) { FUZZ_BAIL(); }

std::vector<float> in(n);
// Fill input floats from bytes deterministically
for (size_t i = 0; i < n; ++i) {
    float v = 0.0f;
    memcpy(&v, bytes.data() + i * sizeof(float), sizeof(float));
    in[i] = v;
}
std::vector<float> out(n, 0.0f);

// Call target
_relu(in.data(), out.data(), (int)n);

// Property: ReLU output must be non-negative
for (size_t i = 0; i < n; ++i) {
    if (!(out[i] >= 0.0f)) { FUZZ_ASSERT(false, "ReLU output must be non-negative"); }
}
// Validation: constructs valid non-overlapping buffers and enforces basic ReLU property (out >= 0).

// Prepare input/output buffers similarly to _relu
std::string bytes = FUZZ_PARAM_STR();
size_t n = bytes.size() / sizeof(float);
if (n > 256) n = 256;
if (n == 0) { FUZZ_BAIL(); }

std::vector<float> in(n);
for (size_t i = 0; i < n; ++i) {
    float v = 0.0f;
    memcpy(&v, bytes.data() + i * sizeof(float), sizeof(float));
    in[i] = v;
}
std::vector<float> out(n, 0.0f);

_gelu(in.data(), out.data(), (int)n);

// Property: outputs should be finite numbers for finite inputs
for (size_t i = 0; i < n; ++i) {
    if (std::isfinite(in[i])) {
        if (!std::isfinite(out[i])) { FUZZ_ASSERT(false, "GELU output must be finite for finite input"); }
    }
}
// Validation: uses distinct buffers, size-bounded, and asserts finiteness for finite inputs.

// Generate a finite input
float x = *FUZZ_PARAM(float);
if (!std::isfinite(x)) { x = 0.0f; }

float y = _sigmoid(x);

// Property: sigmoid outputs are in (0,1) for finite inputs; allow endpoints for extreme inputs due to precision
if (!(y >= 0.0f && y <= 1.0f) || !std::isfinite(y)) {
    FUZZ_ASSERT(false, "Sigmoid output must be finite and within [0,1]");
}
// Validation: constrains input to finite and asserts standard sigmoid range.

// Use fuzz bytes to derive dimensions and data; ensure sizes are small and non-negative
std::string seed = FUZZ_PARAM_STR();
size_t ssz = seed.size();
if (ssz < 16) { FUZZ_BAIL(); }

auto rd32 = [&](size_t off){ uint32_t v=0; memcpy(&v, seed.data() + (off % (ssz-3)), 4); return v; };
uint32_t r1 = rd32(0), r2 = rd32(4), r3 = rd32(8);

int batch_size = (int)(r1 % 8) + 1;   // 1..8
int input_dim  = (int)(r2 % 16) + 1;  // 1..16
int output_dim = (int)(r3 % 16) + 1;  // 1..16

// Bound total buffer sizes to keep < 2048 bytes per buffer
size_t in_elems  = (size_t)batch_size * (size_t)input_dim;
size_t w_elems   = (size_t)input_dim * (size_t)output_dim;
size_t out_elems = (size_t)batch_size * (size_t)output_dim;
if (in_elems > 512 || w_elems > 512 || out_elems > 512) { FUZZ_BAIL(); }

// Allocate and fill inputs from seed bytes (cycle if needed)
auto fill_floats = [&](std::vector<float>& v){
    size_t need = v.size() * sizeof(float);
    for (size_t i = 0; i < v.size(); ++i) {
        float f = 0.0f;
        size_t off = (i * sizeof(float)) % ssz;
        if (off + sizeof(float) <= ssz) {
            memcpy(&f, seed.data() + off, sizeof(float));
        } else {
            // wrap-around copy
            unsigned char tmp[4] = {0,0,0,0};
            size_t first = ssz - off;
            memcpy(tmp, seed.data() + off, first);
            memcpy(tmp + first, seed.data(), sizeof(float) - first);
            memcpy(&f, tmp, sizeof(float));
        }
        v[i] = f;
    }
};

std::vector<float> input(in_elems);
std::vector<float> weights(w_elems);
std::vector<float> bias(output_dim);
std::vector<float> output(out_elems, 0.0f);
fill_floats(input);
fill_floats(weights);
fill_floats(bias);

// Call target
_linear(input.data(), weights.data(), bias.data(), output.data(), batch_size, input_dim, output_dim);

// Basic sanity: outputs should be finite if all inputs are finite
bool all_in_finite = true;
for (size_t i = 0; i < input.size(); ++i) { if (!std::isfinite(input[i])) { all_in_finite = false; break; } }
if (all_in_finite) {
    for (size_t i = 0; i < weights.size(); ++i) { if (!std::isfinite(weights[i])) { all_in_finite = false; break; } }
}
if (all_in_finite) {
    for (size_t i = 0; i < bias.size(); ++i) { if (!std::isfinite(bias[i])) { all_in_finite = false; break; } }
}
if (all_in_finite) {
    for (size_t i = 0; i < output.size(); ++i) {
        if (!std::isfinite(output[i])) { FUZZ_ASSERT(false, "Linear output must be finite for finite inputs"); }
    }
}
// Validation: constructs size-consistent, non-overlapping buffers and asserts finiteness under finite inputs.
